import {stores,provenance} from './data.mjs';
import {DEFAULT_FILTERS,filterStores,rating,internalReviews,restoreState} from './model.mjs';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={search:'<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 5 5"/>',filter:'<path d="M4 6h7m4 0h5M4 12h2m4 0h10M4 18h10m4 0h2"/><circle cx="13" cy="6" r="2"/><circle cx="8" cy="12" r="2"/><circle cx="16" cy="18" r="2"/>',back:'<path d="m14 5-7 7 7 7M7 12h14"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',chevron:'<path d="m9 5 7 7-7 7"/>',fit:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/><circle cx="12" cy="12" r="3"/>'};
const ico=(n,s=20)=>`<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||''}</svg>`;
const copy={ru:{title:'Рестораны на карте',eyebrow:'ОТКРОЙТЕ СВОЙ ВКУС',search:'Ресторан или филиал',filters:'Фильтры',open:'Открыто',closed:'Закрыто',openNow:'Открыто сейчас',all:'Все',restaurant:'Рестораны',cafe:'Кафе',fastfood:'Фастфуд',types:'Тип заведения',rating:'Оценка TALABOT',anyRating:'Любая оценка',four:'От 4,0',fourHalf:'От 4,5',apply:'Показать',reset:'Сбросить',results:'Найдено',list:'Списком',showAll:'Показать на карте',menu:'Меню',reviews:'Отзывы',reviewCount:'отзывов',none:'Нет оценок',unavailable:'Оценки недоступны',noResults:'Ничего не найдено',tryAgain:'Измените поиск или фильтры',details:'Ресторан и меню',back:'Назад к карте',demo:'Демо',demoPoints:'Демо-точки · Душанбе',sample:'Демонстрационное меню и цены. Заказ не оформляется.',illustration:'Иллюстрация',reviewSample:'Демо-отзывы о ресторане. Только пример внутренних оценок TALABOT.',noReviews:'У этого филиала пока нет отзывов.',sourceTitle:'Об этой карте',sourceText:'Это отдельная дизайн-демонстрация. Все названия, филиалы, координаты, статусы, блюда, цены и отзывы — вымышленные примеры, а не действующие партнёры или данные сервера.',sourceMap:'Подложка: OpenStreetMap. Движок: Leaflet 1.9.4 — тот же, что уже используется в TALABOT. Изображения — существующие иллюстрации приложения, не фотографии ресторанов.',sourceRating:'Оценки считаются отдельно по ID филиала из демонстрационных restaurant-only отзывов. Google Reviews и внешние оценки не используются. Реальные отзывы и меню не подключены.',close:'Закрыть',mapFailure:'Не удалось загрузить карту. Список ресторанов доступен.',tileFailure:'Подложка карты недоступна. Точки остаются видны; проверьте подключение.',retry:'Повторить',branch:'Филиал',mainMenu:'Меню ресторана',zoomIn:'Увеличить карту',zoomOut:'Уменьшить карту',viewAll:'Показать все рестораны'},en:{title:'Restaurants on the map',eyebrow:'FIND YOUR NEXT FAVOURITE',search:'Restaurant or branch',filters:'Filters',open:'Open',closed:'Closed',openNow:'Open now',all:'All',restaurant:'Restaurants',cafe:'Cafés',fastfood:'Fast food',types:'Restaurant type',rating:'TALABOT rating',anyRating:'Any rating',four:'4.0 and up',fourHalf:'4.5 and up',apply:'Show results',reset:'Reset',results:'Found',list:'List view',showAll:'Show on map',menu:'Menu',reviews:'Reviews',reviewCount:'reviews',none:'No ratings yet',unavailable:'Ratings unavailable',noResults:'No matches',tryAgain:'Try another search or change your filters',details:'Restaurant & menu',back:'Back to map',demo:'Demo',demoPoints:'Demo pins · Dushanbe',sample:'Demonstration menu and prices. Ordering is not connected.',illustration:'Illustration',reviewSample:'Demo restaurant reviews. Examples of internal TALABOT ratings only.',noReviews:'This branch has no reviews yet.',sourceTitle:'About this map',sourceText:'This is a separate design demonstration. Every name, branch, coordinate, status, dish, price and review is an authored example, not a real partner or server record.',sourceMap:'Basemap: OpenStreetMap. Engine: Leaflet 1.9.4, already used by TALABOT. Pictures are existing app illustrations, not restaurant photographs.',sourceRating:'Ratings are calculated per branch ID from demonstration restaurant-only reviews. No Google Reviews or external scores are used. Live reviews and menus are not connected.',close:'Close',mapFailure:'The map could not load. The restaurant list is still available.',tileFailure:'Map tiles are unavailable. Pins remain visible; check your connection.',retry:'Retry',branch:'Branch',mainMenu:'Restaurant menu',zoomIn:'Zoom in',zoomOut:'Zoom out',viewAll:'Show all restaurants'}};
function read(key){try{return JSON.parse(sessionStorage.getItem(key))}catch{return null}}
function write(key,value){try{sessionStorage.setItem(key,JSON.stringify(value))}catch{/* Preview remains usable when storage is disabled. */}}
let lang=read('talabot-map-language')||(/^ru|^tg/i.test(navigator.language)?'ru':'en');if(!copy[lang])lang='ru';
let state=restoreState(read('talabot-map-v1'),stores),view={page:'map'},map,layer,tiles,markers=new Map(),draft,dialogReturn;
const t=k=>copy[lang][k]||k,tr=v=>v[lang]||v.ru,byId=id=>stores.find(s=>s.id===id);
const resultStores=()=>filterStores(stores,state.filters);
function capture(){if(map){const c=map.getCenter();state.center=[c.lat,c.lng];state.zoom=map.getZoom()}state.listScroll=$('results').scrollTop;write('talabot-map-v1',state);return structuredClone(state)}
function score(s){const r=rating(s);return r.state==='ready'?`<span class="rating"><span class="stars" aria-hidden="true">★</span> ${r.average.toFixed(1)} <span class="muted">(${r.count})</span></span>`:`<span class="muted">${t(r.state==='empty'?'none':'unavailable')}</span>`}
function stars(n){return `<span class="stars" aria-label="${n} / 5">${'★'.repeat(n)}<span style="color:#c9ced5">${'★'.repeat(5-n)}</span></span>`}
function card(s){return `<button class="result ${state.selected===s.id?'selected':''}" data-action="select" data-id="${s.id}" aria-label="${esc(tr(s.name)+' · '+tr(s.branch))}"><img class="thumb" src="${s.image}" alt="${t('illustration')}" width="64" height="64"><span class="text"><span class="name">${esc(tr(s.name))}</span><span class="small muted">${esc(tr(s.branch))} · ${t(s.category)}</span><span class="meta">${score(s)}<span class="${s.is_open?'open':'closed'}">· ${t(s.is_open?'open':'closed')}</span></span></span><span class="chevron">${ico('chevron',17)}</span></button>`}
function pin(s){const r=rating(s);return `<div class="pin ${state.selected===s.id?'selected':''} ${s.is_open?'':'is-closed'}"><img src="${s.image}" alt=""><span><strong>${esc(tr(s.name))}</strong><small><span class="pin-state"></span>${t(s.is_open?'open':'closed')} · ${r.state==='ready'?`<span class="stars">★</span> ${r.average.toFixed(1)}`:'—'}</small></span></div>`}
function renderList(){const previousScroll=state.listScroll;const list=resultStores();if(!list.some(s=>s.id===state.selected))state.selected=null;
  $('count').textContent=`${t('results')}: ${list.length}`;$('results').innerHTML=list.length?list.map(card).join(''):`<div class="empty"><h3>${t('noResults')}</h3><p class="muted">${t('tryAgain')}</p><button class="text-button" data-action="reset">${t('reset')}</button></div>`;
  $('chips').innerHTML=`<button class="chip ${state.filters.openOnly?'on':''}" data-action="open">${t('openNow')}</button><button class="chip ${state.filters.minRating===4.5?'on':''}" data-action="rating"><span class="star">★</span> 4.5+</button><button class="chip ${state.filters.category?'on':''}" data-action="filter">${t(state.filters.category||'types')} ${ico('chevron',12)}</button>`;
  $('filters').classList.toggle('on',!!(state.filters.category||state.filters.openOnly||state.filters.minRating));
  if(layer){layer.clearLayers();markers.clear();list.forEach(s=>{const m=L.marker([s.lat,s.lng],{icon:L.divIcon({className:'pin-wrap',html:pin(s),iconSize:[130,46],iconAnchor:[65,53]}),title:tr(s.name)+' · '+tr(s.branch),keyboard:true,zIndexOffset:state.selected===s.id?1000:0}).addTo(layer).on('click',()=>selectStore(s.id,false));markers.set(s.id,m);const el=m.getElement();el?.setAttribute('aria-label',`${tr(s.name)} · ${tr(s.branch)} · ${t(s.is_open?'open':'closed')} · ${rating(s).state==='ready'?rating(s).average:t('none')}`)})}
  $('results').scrollTop=previousScroll;renderSelection();capture();
}
function renderSelection(){const s=byId(state.selected);$('selection').hidden=!s;if(!s)return;
  $('selection').innerHTML=`<div class="selection-head"><img class="thumb" src="${s.image}" alt="${t('illustration')}"><div class="info"><h2>${esc(tr(s.name))} <span class="muted">· ${esc(tr(s.branch))}</span></h2><div class="summary-meta">${score(s)}<span class="${s.is_open?'open':'closed'}">${t(s.is_open?'open':'closed')}</span></div></div><button class="icon-button" data-action="deselect" aria-label="${t('close')}">${ico('close')}</button></div><p class="address">${esc(tr(s.address))}</p><button class="primary" data-action="restaurant" data-id="${s.id}">${t('details')} →</button>`;
}
function selectStore(id,pan=true){state.selected=id;if($('dialog').open)$('dialog').close();renderList();if(pan&&map){const s=byId(id);map.panTo([s.lat,s.lng],{animate:false})}write('talabot-map-v1',state)}
function fit(){const list=resultStores();if(map&&list.length)map.fitBounds(list.map(s=>[s.lat,s.lng]),{padding:[75,75],maxZoom:15,animate:false})}
function renderLabels(){document.documentElement.lang=lang;document.title='TALABOT — '+t('title');$('title').textContent=t('title');$('eyebrow').textContent=t('eyebrow');$('search').placeholder=t('search');$('search').setAttribute('aria-label',t('search'));$('search').value=state.filters.query;$('filters').setAttribute('aria-label',t('filters'));$('filters').innerHTML=ico('filter');$('search-icon').innerHTML=ico('search');$('show-list').textContent=t('list');$('map-caption').textContent=t('demoPoints');$('source').textContent=t('demo');$('language').textContent=lang==='ru'?'EN':'RU';$('language').setAttribute('aria-label',lang==='ru'?'Switch to English':'Переключить на русский');$('zoom-in').setAttribute('aria-label',t('zoomIn'));$('zoom-out').setAttribute('aria-label',t('zoomOut'));$('fit').setAttribute('aria-label',t('viewAll'));$('fit').innerHTML=ico('fit');$('dialog-close').innerHTML=ico('close');$('dialog-close').setAttribute('aria-label',t('close'))}
function openDialog(title,html){dialogReturn=document.activeElement;$('dialog-title').textContent=title;$('dialog-body').innerHTML=html;$('dialog').showModal()}
function filterHTML(){return `<div class="filter-group"><label class="filter-label" for="category">${t('types')}</label><select class="filter-select" id="category">${['','restaurant','cafe','fastfood'].map(v=>`<option value="${v}" ${draft.category===v?'selected':''}>${t(v||'all')}</option>`).join('')}</select></div><div class="filter-group"><label class="filter-label" for="min-rating">${t('rating')}</label><select class="filter-select" id="min-rating">${[[0,'anyRating'],[4,'four'],[4.5,'fourHalf']].map(([v,k])=>`<option value="${v}" ${draft.minRating===v?'selected':''}>${t(k)}</option>`).join('')}</select></div><div class="filter-group"><label class="filter-label"><input type="checkbox" id="only-open" ${draft.openOnly?'checked':''}> ${t('openNow')}</label></div><div class="filter-footer"><button class="text-button" data-action="filter-reset">${t('reset')}</button><button class="primary" data-action="filter-apply">${t('apply')}</button></div>`}
function openFilters(){draft={...state.filters};openDialog(t('filters'),filterHTML())}
function renderRestaurant(){const s=byId(view.id);if(!s)return goMap();const r=rating(s),siblings=stores.filter(x=>x.brand_id===s.brand_id&&x.is_active);$('restaurant').innerHTML=`<div class="restaurant-top"><button class="icon-button" data-action="back" aria-label="${t('back')}">${ico('back')}</button><span>${t('back')}</span></div><div class="cover"><img src="${s.image}" alt="${t('illustration')}"><span class="small">${t('demo')} · ${t('illustration')}</span></div><div class="restaurant-main"><div class="restaurant-title"><img class="thumb" src="${s.image}" alt=""><div><h1>${esc(tr(s.name))}</h1><p class="small muted">${esc(tr(s.branch))} · ${t(s.category)}</p></div></div><div class="info-line">${score(s)}<span class="${s.is_open?'open':'closed'}">${t(s.is_open?'open':'closed')}</span></div><p class="small muted">${esc(tr(s.address))}</p>${siblings.length>1?`<div class="branch-choice">${siblings.map(x=>`<button class="chip ${x.id===s.id?'on':''}" data-action="branch" data-id="${x.id}">${esc(tr(x.branch))}</button>`).join('')}</div>`:''}<nav class="tabs" aria-label="${t('details')}"><button data-action="tab" data-tab="menu" class="${view.tab==='menu'?'on':''}" aria-current="${view.tab==='menu'?'page':'false'}">${t('menu')}</button><button data-action="tab" data-tab="reviews" class="${view.tab==='reviews'?'on':''}" aria-current="${view.tab==='reviews'?'page':'false'}">${t('reviews')} (${r.count??'—'})</button></nav>${view.tab==='reviews'?reviewsHTML(s):menuHTML(s)}</div>`}
function menuHTML(s){return `<h2>${t('mainMenu')}</h2><div class="sample-notice">${t('sample')}</div>${s.menu.map(m=>`<article class="menu-item"><div><h3>${esc(tr(m.name))}</h3><p>${esc(tr(m.description))}</p><strong>${m.price.toFixed(2)} TJS</strong></div><img src="${m.image}" alt="${t('illustration')}"></article>`).join('')}`}
function reviewsHTML(s){const r=rating(s);return `<div class="review-summary"><strong>${r.average?.toFixed(1)||'—'}</strong><div><b>${t('rating')}</b><p class="small muted">${r.count??'—'} ${t('reviewCount')}</p></div></div><div class="sample-notice">${t('reviewSample')}</div>${internalReviews(s).map(r=>`<article class="review"><header><b>${esc(tr(r.author))}</b><time datetime="${r.date}">${new Date(r.date+'T12:00:00Z').toLocaleDateString(lang==='ru'?'ru-RU':'en-GB',{day:'numeric',month:'short',year:'numeric'})}</time></header>${stars(r.stars)}<p>${esc(tr(r.comment))}</p></article>`).join('')||`<p class="muted">${t('noReviews')}</p>`}`}
function navigateRestaurant(id){history.replaceState({page:'map',map:capture()},'',location.pathname+location.search);view={page:'restaurant',id,tab:'menu'};history.pushState(view,'','#restaurant/'+id);$('explore').hidden=true;$('restaurant').hidden=false;renderRestaurant();window.scrollTo(0,0)}
function goMap(snapshot){if(snapshot)state=restoreState(snapshot,stores);view={page:'map'};$('restaurant').hidden=true;$('explore').hidden=false;renderLabels();if(map){map.invalidateSize();map.setView(state.center,state.zoom,{animate:false})}const scroll=state.listScroll;renderList();$('results').scrollTop=scroll;window.scrollTo(0,0)}
function mapError(key){$('map-error').hidden=false;$('map-error').innerHTML=`${t(key)}<button data-action="retry">${t('retry')}</button>`}
function initMap(){if(!window.L){mapError('mapFailure');$('show-list').style.display='block';return}map=L.map('map',{zoomControl:false,minZoom:10,maxZoom:19,zoomAnimation:!matchMedia('(prefers-reduced-motion: reduce)').matches}).setView(state.center,state.zoom);tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>'}).addTo(map);layer=L.layerGroup().addTo(map);let tileErrors=0;tiles.on('tileerror',()=>{tileErrors++;if(tileErrors>=3)mapError('tileFailure')});tiles.on('tileload',()=>{tileErrors=0;$('map-error').hidden=true});map.on('moveend zoomend',capture);map.on('click',()=>{if(state.selected){state.selected=null;renderList()}});renderList()}
$('results').addEventListener('scroll',()=>{state.listScroll=$('results').scrollTop});
$('search').addEventListener('input',e=>{state.listScroll=0;state.filters.query=e.target.value;renderList()});$('filters').onclick=openFilters;$('source').onclick=()=>openDialog(t('sourceTitle'),`<div class="source-copy"><p>${t('sourceText')}</p><p>${t('sourceMap')}</p><p>${t('sourceRating')}</p><p class="small muted">MAP-RESTAURANTS-01 · ${provenance.catalog}</p><code>${provenance.policy}</code></div>`);$('language').onclick=()=>{lang=lang==='ru'?'en':'ru';write('talabot-map-language',lang);renderLabels();renderList();if(view.page==='restaurant')renderRestaurant()};$('show-list').onclick=()=>openDialog(t('title'),resultStores().map(card).join('')||`<p>${t('noResults')}</p>`);$('zoom-in').onclick=()=>map?.zoomIn();$('zoom-out').onclick=()=>map?.zoomOut();$('fit').onclick=fit;$('dialog-close').onclick=()=>$('dialog').close();$('dialog').addEventListener('close',()=>dialogReturn?.focus?.());$('dialog').addEventListener('click',e=>{if(e.target===$('dialog')){const r=$('dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('dialog').close()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;switch(b.dataset.action){case'select':selectStore(b.dataset.id);break;case'deselect':state.selected=null;renderList();break;case'restaurant':navigateRestaurant(b.dataset.id);break;case'back':history.back();break;case'branch':view.id=b.dataset.id;history.replaceState(view,'','#restaurant/'+view.id);renderRestaurant();break;case'tab':view.tab=b.dataset.tab;history.replaceState(view,'','#restaurant/'+view.id+'/'+view.tab);renderRestaurant();break;case'open':state.filters.openOnly=!state.filters.openOnly;renderList();break;case'rating':state.filters.minRating=state.filters.minRating===4.5?0:4.5;renderList();break;case'filter':openFilters();break;case'reset':state.filters={...DEFAULT_FILTERS};renderLabels();renderList();break;case'filter-reset':draft={...DEFAULT_FILTERS};$('dialog-body').innerHTML=filterHTML();break;case'filter-apply':state.filters={query:state.filters.query,category:$('category').value,minRating:Number($('min-rating').value),openOnly:$('only-open').checked};$('dialog').close();renderList();fit();break;case'retry':if(tiles){tiles.redraw();$('map-error').hidden=true}else location.reload();break}});
window.addEventListener('popstate',e=>{if($('dialog').open)$('dialog').close();if(e.state?.page==='restaurant'){view=e.state;$('explore').hidden=true;$('restaurant').hidden=false;renderRestaurant()}else goMap(e.state?.map)});window.addEventListener('pagehide',capture);window.addEventListener('resize',()=>map?.invalidateSize());
renderLabels();history.replaceState({page:'map',map:structuredClone(state)},'',location.pathname+location.search);renderList();initMap();
